answerCalls.rawCandidateText:
{
  "directAnswer": "As a general explanatory principle under Singapore Goods and Services Tax (GST) rules, input tax incurred on business entertainment expenses (including meals with customers or suppliers) is typically allowed for claim if it is incurred for the purpose of your business and supported by a valid tax invoice (or simplified tax invoice/receipt as permitted under administrative concessions). However, input tax on entertainment provided to non-business visitors, or private expenses, cannot be claimed.",
  "keyRules": [
    "Under IRAS guidelines, input tax claims on entertainment expenses are subject to the general conditions for input tax recovery, including holding a valid tax invoice addressed to the business or a simplified tax invoice if the purchase value including GST is not more than $1,000.",
    "As an administrative concession, a receipt containing all information required in a simplified tax invoice can be used to claim input tax incurred on entertainment expenses exceeding $1,000 including GST.",
    "GST incurred on expenses that are private in nature or not incurred for the purpose of the business is strictly unclaimable."
  ],
  "caveats": [
    "The expense must have a direct business purpose (e.g., hosting a commercial customer or supplier for business discussions).",
    "Proper documentation, including valid tax invoices/receipts and records indicating the business purpose and attendees, must be retained for at least 5 years.",
    "Missing facts: Supplier and customer GST registration status, business purpose of the meal, and details of who attended must be confirmed to determine exact claimability."
  ],
  "statuteReferences": [
    {
      "standard": "Goods and Services Tax Act 1993",
      "paragraph": "General Input Tax Claim Provisions",
      "authority": "IRAS",
      "officialSourceUrl": "https://sso.agc.gov.sg/Act/GSTA1993"
    }
  ]
}

