answerCalls.rawCandidateText:
{
  "directAnswer": "Under Singapore Goods and Services Tax rules, input tax incurred on the acquisition, rental, or running expenses of a motor car (specifically a passenger car) is generally disallowed (blocked input tax) under Regulation 26 of the GST (General) Regulations, unless specific statutory exceptions apply (such as cars registered as commercial vehicles like taxis or driving school cars).",
  "keyRules": [
    "Input tax claims on motor cars are generally blocked under Regulation 26 of the GST (General) Regulations.",
    "A motor car is defined under the rules to mean any motor car constructed or adapted for the carriage of not more than 7 passengers (excluding the driver) and the unladen weight of which does not exceed 3,000 kilograms.",
    "Exceptions where input tax may be claimed include vehicles registered strictly for commercial use (e.g. buses, goods vehicles, taxis, or vehicles used exclusively as stock-in-trade by a motor dealer)."
  ],
  "caveats": [
    "Running expenses (such as fuel and maintenance) associated with a blocked passenger car are similarly non-claimable for input tax.",
    "The company must verify whether the specific vehicle falls under the statutory definition of a 'motor car' or qualifies for an approved commercial exception."
  ],
  "statuteReferences": [
    {
      "standard": "GST (General) Regulations",
      "paragraph": "Regulation 26",
      "authority": "IRAS",
      "officialSourceUrl": "https://sso.agc.gov.sg/SL/GSTA1993-RG1"
    }
  ]
}

