answerCalls.rawCandidateText:
{
  "directAnswer": "Under general tax principles in Singapore, renovation or refurbishment (R&R) expenditure is capital in nature and is not immediately deductible as a general business expense under Section 14(1) of the Income Tax Act 1947. However, specific statutory provisions under Section 14N allow qualifying non-structural R&R expenditure to be claimed as a tax deduction subject to statutory caps and conditions.",
  "keyRules": [
    "Section 14N of the Income Tax Act 1947 allows qualifying non-structural renovation or refurbishment expenditure incurred by a business carrying on a trade, profession, or vocation to be deducted.",
    "Expenditure is subject to an expenditure cap (e.g., $300,000 for every relevant 3-year period under current rules, or specific fixed periods starting from YA 2025).",
    "Qualifying expenditure must be non-structural and excludes items such as designer or professional fees (subject to Budget 2024 updates for YA 2025 onwards), antiques, fine art, and works carried out to employee residences."
  ],
  "caveats": [
    "Investment holding companies do not qualify for Section 14N deductions because they do not carry on a trade, business, or profession for tax purposes.",
    "Renovation costs that affect the structure of the business premises do not qualify for Section 14N deductions, though they may potentially qualify for Land Intensification Allowance if approved by the EDB or BCA.",
    "Exact deductibility depends on the precise nature of the work, the exact basis period, and whether the business continues to carry on the trade for which the expenditure was incurred."
  ],
  "statuteReferences": [
    {
      "standard": "Income Tax Act 1947",
      "paragraph": "Section 14(1)",
      "authority": "IRAS",
      "officialSourceUrl": "https://sso.agc.gov.sg/Act/ITA1947?ProvIds=pr14-"
    },
    {
      "standard": "Income Tax Act 1947",
      "paragraph": "Section 14N",
      "authority": "IRAS",
      "officialSourceUrl": "https://www.iras.gov.sg/taxes/corporate-income-tax/income-deductions-for-companies/business-expenses/tax-treatment-of-business-expenses-(m-r)"
    }
  ]
}

