answerCalls.rawCandidateText:
{
  "directAnswer": "For qualifying non-structural renovation and refurbishment (R&R) expenditure incurred in the basis period relating to YA 2026, the company should check the fixed 3-year cap period from YA 2025 to YA 2027 under Section 14N of the Income Tax Act 1947, where the total qualifying R&R expenditure is capped at SGD 300,000 for the entire fixed 3-year period. In addition, the company should verify whether it elects for a 1-year write-off or claims over the standard period, subject to prior cap utilization and whether it carries on an active trade, business, or profession.",
  "keyRules": [
    "Section 14N expenditure is capped at SGD 300,000 for each fixed 3-year period, with the first fixed period running from YA 2025 to YA 2027.",
    "Qualifying expenditure incurred in YA 2026 contributes toward the remaining cap balance within the fixed YA 2025–YA 2027 period (i.e., SGD 300,000 minus any amounts already allowed in YA 2025).",
    "Designer and professional fees that do not relate to structural works requiring Building Control approval are included as qualifying R&R expenditure effective from YA 2025."
  ],
  "caveats": [
    "Investment holding companies do not qualify for Section 14N deductions as they do not carry on a trade or business for tax purposes.",
    "The deduction applies only to qualifying non-structural renovation and refurbishment works and excludes items that affect the structure of business premises, fine art, or works to employee residences.",
    "The company must maintain proper supporting documentation of all incurred R&R expenditures for submission upon IRAS request."
  ],
  "statuteReferences": [
    {
      "standard": "Income Tax Act 1947",
      "paragraph": "Section 14N",
      "authority": "IRAS",
      "officialSourceUrl": "https://sso.agc.gov.sg/Act/ITA1947"
    }
  ]
}

