answerCalls.rawCandidateText:
{
  "directAnswer": "Under Singapore tax law, interest paid or made available to a non-resident company is generally subject to withholding tax under Section 45 of the Income Tax Act 1947 if the interest is borne directly or indirectly by a person resident in Singapore or deductible against income derived from Singapore. However, exemptions or reduced rates may apply depending on specific statutory provisions, such as payments made by banks or under qualifying financing arrangements, or relief under an Avoidance of Double Taxation Agreement (DTA).",
  "keyRules": [
    "Section 45 of the Income Tax Act 1947 requires a person who makes interest payments to a non-resident to withhold tax at the prescribed rate.",
    "The statutory withholding tax rate on interest paid to non-residents is 15% (subject to any applicable DTA reduction or specific statutory exemption)."
  ],
  "caveats": [
    "Interest and Section 12(6) payments made by banks, finance companies, and certain approved entities for the purpose of their trade or business are exempt from withholding tax.",
    "Interest paid to a non-resident for a loan obtained from outside Singapore to acquire an overseas immovable property may be exempt if the interest is not deductible against Singapore-derived income.",
    "Recipients may qualify for reduced withholding tax rates if a valid Avoidance of Double Taxation Agreement (DTA) applies and all conditions (such as beneficial ownership and residency certification) are met."
  ],
  "statuteReferences": [
    {
      "standard": "Income Tax Act 1947",
      "paragraph": "Section 45",
      "authority": "IRAS",
      "officialSourceUrl": "https://sso.agc.gov.sg/Act/ITA1947"
    }
  ]
}

